# ============================================================
# 010_quality_dashboard_visualization_tests.R
# Biomedical Quality Dashboard Verification App
# PostgreSQL + R + Shiny
# ============================================================
#
# PURPOSE:
# Interactive verification interface for the metrics generated by
# 09_quality_metrics_backend.R.
#
# This script is designed to help verify that dashboard metrics
# are being calculated correctly by comparing:
#
#   raw database table  ->  intermediate calculation  ->  final metric
#
# IMPORTANT:
# - This script does not modify the database.
# - This script does not insert data.
# - This script does not delete data.
# - This script only reads data and displays verification tables.
# - It is not the final production Shiny app.
# - It is a backend validation and debugging interface.
#
# ACADEMIC FRAMING:
#
# Completeness:
# Measures null values and populated field ratios.
#
# Consistency:
# Measures internal coherence using derived checks such as BMI
# plausibility and available internal consistency metrics.
#
# Accuracy:
# True clinical accuracy requires an external gold standard.
# This app only explores proxy accuracy through validation flags,
# plausibility checks, and statistical outlier detection.
#
# This app does not claim overdose detection, toxic dose detection,
# true diagnostic correctness, or pharmacological safety.
#
# ============================================================

# ------------------------------------------------------------
# Load Required Libraries
# ------------------------------------------------------------

library(DBI)
library(RPostgres)
library(tidyverse)
library(stringr)
library(lubridate)
library(uuid)
library(glue)
library(janitor)
library(ggplot2)
library(shiny)

# ------------------------------------------------------------
# Source Metrics Backend
# ------------------------------------------------------------

source("09_quality_metrics_backend.R")

# ------------------------------------------------------------
# Load Dashboard Context Safely
# ------------------------------------------------------------

load_context_for_app <- function() {

  con <- NULL

  tryCatch({

    con <- connect_db()

    context <- load_dashboard_context(con)

    dashboard_metrics <- generate_dashboard_metrics(context)

    list(
      context = context,
      dashboard_metrics = dashboard_metrics,
      loaded_at = Sys.time(),
      success = TRUE,
      error_message = NA_character_
    )

  }, error = function(e) {

    list(
      context = NULL,
      dashboard_metrics = NULL,
      loaded_at = Sys.time(),
      success = FALSE,
      error_message = e$message
    )

  }, finally = {

    if (!is.null(con)) {

      tryCatch({

        dbDisconnect(con)

      }, error = function(e) {

        message("Connection closing warning in load_context_for_app().")
      })
    }
  })
}

# ------------------------------------------------------------
# Helper: Metric Value Extractor
# ------------------------------------------------------------

get_metric_value <- function(metric_table, metric_name) {

  if (is.null(metric_table) || nrow(metric_table) == 0) {
    return(NA_real_)
  }

  value <- metric_table %>%
    filter(.data$metric_name == !!metric_name) %>%
    pull(.data$metric_value)

  if (length(value) == 0) {
    return(NA_real_)
  }

  return(value[[1]])
}

# ------------------------------------------------------------
# Helper: Manual Missingness Calculation
# ------------------------------------------------------------

manual_missingness_by_variable <- function(context) {

  patients <- context$patients
  fields <- get_evaluated_fields(context)

  if (nrow(patients) == 0 || length(fields) == 0) {

    return(tibble(
      variable_name = character(),
      manual_missing_count = numeric(),
      manual_non_missing_count = numeric(),
      manual_total_records = numeric(),
      manual_missing_percentage = numeric()
    ))
  }

  result <- tibble()

  for (field in fields) {

    values <- patients[[field]]

    if (is.character(values)) {

      missing_count <- sum(is.na(values) | str_trim(values) == "")

    } else {

      missing_count <- sum(is.na(values))
    }

    total_records <- nrow(patients)
    non_missing_count <- total_records - missing_count

    result <- bind_rows(
      result,
      tibble(
        variable_name = field,
        manual_missing_count = missing_count,
        manual_non_missing_count = non_missing_count,
        manual_total_records = total_records,
        manual_missing_percentage = round(
          safe_divide(missing_count, total_records) * 100,
          2
        )
      )
    )
  }

  result %>%
    arrange(desc(.data$manual_missing_percentage), .data$variable_name)
}

# ------------------------------------------------------------
# Helper: Completeness Verification Table
# ------------------------------------------------------------

build_completeness_verification_table <- function(context, dashboard_metrics) {

  backend_table <- dashboard_metrics$missingness_by_variable

  manual_table <- manual_missingness_by_variable(context)

  comparison <- backend_table %>%
    left_join(
      manual_table,
      by = "variable_name"
    ) %>%
    mutate(
      missing_count_match = .data$missing_count == .data$manual_missing_count,
      missing_percentage_match = abs(.data$missing_percentage - .data$manual_missing_percentage) < 0.01
    )

  return(comparison)
}

# ------------------------------------------------------------
# Helper: Manual Record Completeness
# ------------------------------------------------------------

manual_record_completeness <- function(context, selected_patient_id) {

  patients <- context$patients
  fields <- get_evaluated_fields(context)

  patient_row <- patients %>%
    filter(.data$patient_id == !!selected_patient_id)

  if (nrow(patient_row) == 0 || length(fields) == 0) {

    return(tibble(
      variable_name = character(),
      raw_value = character(),
      is_missing = logical()
    ))
  }

  result <- tibble()

  for (field in fields) {

    value <- patient_row[[field]][[1]]

    missing <- if (is.character(value)) {

      is.na(value) || str_trim(value) == ""

    } else {

      is.na(value)
    }

    result <- bind_rows(
      result,
      tibble(
        variable_name = field,
        raw_value = as.character(value),
        is_missing = missing
      )
    )
  }

  result
}

# ------------------------------------------------------------
# Helper: BMI Verification Table
# ------------------------------------------------------------

build_bmi_verification_table <- function(context, dashboard_metrics) {

  patients <- context$patients

  manual_bmi <- patients %>%
    transmute(
      patient_uuid,
      patient_id,
      raw_weight_kg = as.numeric(weight_kg),
      raw_height_cm = as.numeric(height_cm),
      manual_height_m = raw_height_cm / 100,
      manual_bmi = round(raw_weight_kg / (manual_height_m ^ 2), 2),
      manual_bmi = ifelse(
        is.na(raw_weight_kg) |
          is.na(raw_height_cm) |
          raw_height_cm <= 0,
        NA_real_,
        manual_bmi
      )
    )

  dashboard_metrics$bmi_table %>%
    left_join(
      manual_bmi,
      by = c("patient_uuid", "patient_id")
    ) %>%
    mutate(
      bmi_match = case_when(
        is.na(.data$bmi) & is.na(.data$manual_bmi) ~ TRUE,
        abs(.data$bmi - .data$manual_bmi) < 0.01 ~ TRUE,
        TRUE ~ FALSE
      )
    ) %>%
    arrange(.data$patient_id)
}

# ------------------------------------------------------------
# Helper: Dose per Kg Verification Table
# ------------------------------------------------------------

build_dose_per_kg_verification_table <- function(context) {

  patients <- context$patients

  patients %>%
    transmute(
      patient_uuid,
      patient_id,
      dosage_mg = as.numeric(dosage_mg),
      weight_kg = as.numeric(weight_kg),
      manual_dose_per_kg = round(dosage_mg / weight_kg, 4),
      manual_dose_per_kg = ifelse(
        is.na(dosage_mg) |
          is.na(weight_kg) |
          weight_kg <= 0,
        NA_real_,
        manual_dose_per_kg
      )
    ) %>%
    arrange(.data$patient_id)
}

# ------------------------------------------------------------
# Helper: Flag Burden Verification
# ------------------------------------------------------------

build_flag_burden_verification_table <- function(context, dashboard_metrics) {

  patients <- context$patients
  flags <- context$quality_flags

  manual_flag_counts <- flags %>%
    filter(!is.na(.data$patient_uuid)) %>%
    group_by(.data$patient_uuid) %>%
    summarise(
      manual_total_flags = n(),
      manual_warning_flags = sum(.data$severity == "WARNING", na.rm = TRUE),
      manual_critical_flags = sum(.data$severity == "CRITICAL", na.rm = TRUE),
      manual_info_flags = sum(.data$severity == "INFO", na.rm = TRUE),
      .groups = "drop"
    )

  patients %>%
    select(patient_uuid, patient_id) %>%
    left_join(
      dashboard_metrics$flag_burden_per_patient,
      by = c("patient_uuid", "patient_id")
    ) %>%
    left_join(
      manual_flag_counts,
      by = "patient_uuid"
    ) %>%
    mutate(
      manual_total_flags = replace_na(.data$manual_total_flags, 0),
      manual_warning_flags = replace_na(.data$manual_warning_flags, 0),
      manual_critical_flags = replace_na(.data$manual_critical_flags, 0),
      manual_info_flags = replace_na(.data$manual_info_flags, 0),
      total_flags_match = .data$total_flags == .data$manual_total_flags,
      warning_flags_match = .data$warning_flags == .data$manual_warning_flags,
      critical_flags_match = .data$critical_flags == .data$manual_critical_flags,
      info_flags_match = .data$info_flags == .data$manual_info_flags
    ) %>%
    arrange(desc(.data$total_flags), .data$patient_id)
}

# ------------------------------------------------------------
# Helper: Outlier Verification Table
# ------------------------------------------------------------

build_zscore_verification_table <- function(context, variable_name = "bmi") {

  detect_zscore_outliers(
    context = context,
    variable_name = variable_name,
    threshold = 3
  )
}

