# ============================================================
# SERVER
# ============================================================

server <- function(input, output, session) {

  app_data <- reactiveVal(initial_load)

  observeEvent(input$refresh_data, {

    refreshed <- load_context_for_app()

    app_data(refreshed)
  })

  context_reactive <- reactive({

    data <- app_data()

    validate(
      need(isTRUE(data$success), data$error_message)
    )

    data$context
  })

  metrics_reactive <- reactive({

    data <- app_data()

    validate(
      need(isTRUE(data$success), data$error_message)
    )

    data$dashboard_metrics
  })

  output$load_status <- renderPrint({

    data <- app_data()

    list(
      success = data$success,
      loaded_at = data$loaded_at,
      error_message = data$error_message,
      n_patients = if (!is.null(data$context)) nrow(data$context$patients) else NA,
      n_quality_flags = if (!is.null(data$context)) nrow(data$context$quality_flags) else NA,
      n_rejected_submissions = if (!is.null(data$context)) nrow(data$context$rejected_patient_submissions) else NA
    )
  })

  output$patient_selector_ui <- renderUI({

    context <- context_reactive()

    patient_choices <- context$patients %>%
      arrange(.data$patient_id) %>%
      pull(.data$patient_id)

    selectInput(
      inputId = "selected_patient_id",
      label = "Patient to inspect",
      choices = patient_choices,
      selected = patient_choices[[1]]
    )
  })

  # ----------------------------------------------------------
  # Overview Outputs
  # ----------------------------------------------------------

  output$completeness_summary <- renderTable({

    metrics_reactive()$completeness_summary
  })

  output$flag_burden_summary <- renderTable({

    metrics_reactive()$flag_burden_summary
  })

  output$hot_cold_ratio <- renderTable({

    metrics_reactive()$hot_cold_ratio
  })

  # ----------------------------------------------------------
  # Raw Patients Outputs
  # ----------------------------------------------------------

  output$patients_preview <- renderTable({

    context_reactive()$patients %>%
      arrange(.data$patient_id) %>%
      head(25)
  })

  output$patients_schema <- renderTable({

    context_reactive()$patients %>%
      summarise(across(everything(), ~class(.)[[1]])) %>%
      pivot_longer(
        cols = everything(),
        names_to = "column_name",
        values_to = "r_class"
      )
  })

  # ----------------------------------------------------------
  # Completeness Verification
  # ----------------------------------------------------------

  output$completeness_verification <- renderTable({

    build_completeness_verification_table(
      context = context_reactive(),
      dashboard_metrics = metrics_reactive()
    )
  })

  output$missingness_plot <- renderPlot({

    plot_data <- metrics_reactive()$missingness_by_variable %>%
      arrange(desc(.data$missing_percentage)) %>%
      mutate(
        variable_name = factor(.data$variable_name, levels = .data$variable_name)
      )

    ggplot(
      plot_data,
      aes(x = variable_name, y = missing_percentage)
    ) +
      geom_col() +
      coord_flip() +
      labs(
        title = "Missingness by Variable",
        x = "Variable",
        y = "Missing Values (%)"
      ) +
      theme_minimal()
  })

  # ----------------------------------------------------------
  # Patient-level Completeness
  # ----------------------------------------------------------

  output$selected_patient_missingness <- renderTable({

    req(input$selected_patient_id)

    manual_record_completeness(
      context = context_reactive(),
      selected_patient_id = input$selected_patient_id
    )
  })

  output$selected_patient_backend_completeness <- renderTable({

    req(input$selected_patient_id)

    metrics_reactive()$missingness_by_patient %>%
      filter(.data$patient_id == input$selected_patient_id)
  })

  output$record_completeness_plot <- renderPlot({

    ggplot(
      metrics_reactive()$missingness_by_patient,
      aes(x = record_completeness_percentage)
    ) +
      geom_histogram(bins = 20) +
      coord_cartesian(xlim = c(0, 100)) +
      labs(
        title = "Record Completeness Distribution",
        x = "Record Completeness (%)",
        y = "Number of Patients"
      ) +
      theme_minimal()
  })

  # ----------------------------------------------------------
  # BMI Verification
  # ----------------------------------------------------------

  output$bmi_verification <- renderTable({

    build_bmi_verification_table(
      context = context_reactive(),
      dashboard_metrics = metrics_reactive()
    ) %>%
      arrange(.data$bmi_match, .data$patient_id) %>%
      head(50)
  })

  output$bmi_category_plot <- renderPlot({

    plot_data <- metrics_reactive()$bmi_table %>%
      count(.data$bmi_category, name = "n")

    ggplot(
      plot_data,
      aes(x = bmi_category, y = n)
    ) +
      geom_col() +
      labs(
        title = "BMI Category Distribution",
        x = "BMI Category",
        y = "Number of Patients"
      ) +
      theme_minimal()
  })

  # ----------------------------------------------------------
  # Dose per Kg / Z-score Verification
  # ----------------------------------------------------------

  output$dose_per_kg_table <- renderTable({

    build_dose_per_kg_verification_table(
      context = context_reactive()
    ) %>%
      arrange(desc(.data$manual_dose_per_kg)) %>%
      head(50)
  })

  output$zscore_outliers <- renderTable({

    build_zscore_verification_table(
      context = context_reactive(),
      variable_name = input$zscore_variable
    )
  })

  output$zscore_plot <- renderPlot({

    plot_data <- build_zscore_verification_table(
      context = context_reactive(),
      variable_name = input$zscore_variable
    )

    if (nrow(plot_data) == 0) {

      plot.new()
      text(
        x = 0.5,
        y = 0.5,
        labels = "No z-score outliers detected for selected variable."
      )

    } else {

      ggplot(
        plot_data,
        aes(x = patient_id, y = z_score)
      ) +
        geom_col() +
        coord_flip() +
        labs(
          title = glue("Z-score Outliers: {input$zscore_variable}"),
          x = "Patient ID",
          y = "Z-score"
        ) +
        theme_minimal()
    }
  })

  # ----------------------------------------------------------
  # Flags Verification
  # ----------------------------------------------------------

  output$quality_flags_preview <- renderTable({

    context_reactive()$quality_flags %>%
      arrange(desc(.data$created_at)) %>%
      head(50)
  })

  output$flag_burden_verification <- renderTable({

    build_flag_burden_verification_table(
      context = context_reactive(),
      dashboard_metrics = metrics_reactive()
    ) %>%
      filter(
        .data$total_flags > 0 |
          .data$manual_total_flags > 0
      ) %>%
      arrange(desc(.data$total_flags), .data$patient_id)
  })

  output$problematic_variables_plot <- renderPlot({

    plot_data <- metrics_reactive()$most_problematic_variables %>%
      arrange(desc(.data$total_flags)) %>%
      mutate(
        variable_name = factor(.data$variable_name, levels = .data$variable_name)
      )

    if (nrow(plot_data) == 0) {

      plot.new()
      text(
        x = 0.5,
        y = 0.5,
        labels = "No quality flags available."
      )

    } else {

      ggplot(
        plot_data,
        aes(x = variable_name, y = total_flags)
      ) +
        geom_col() +
        coord_flip() +
        labs(
          title = "Most Problematic Variables",
          x = "Variable",
          y = "Total Quality Flags"
        ) +
        theme_minimal()
    }
  })

  # ----------------------------------------------------------
  # Confidence Score
  # ----------------------------------------------------------

  output$confidence_score_table <- renderTable({

    metrics_reactive()$record_confidence_score %>%
      arrange(.data$confidence_score) %>%
      head(50)
  })

  output$confidence_score_plot <- renderPlot({

    ggplot(
      metrics_reactive()$record_confidence_score,
      aes(x = confidence_score)
    ) +
      geom_histogram(bins = 20) +
      coord_cartesian(xlim = c(0, 100)) +
      labs(
        title = "Record Confidence Score Distribution",
        x = "Confidence Score",
        y = "Number of Patients"
      ) +
      theme_minimal()
  })
}

# ============================================================
# Run App
# ============================================================

shinyApp(ui = ui, server = server)